{
  "findings": [
    {
      "check_id": "CKV2_GCP_19",
      "title": "Ensure GCP Kubernetes engine clusters have 'alpha cluster' feature disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The 'enable_kubernetes_alpha' feature is enabled, which allows alpha features that are not production-ready and may introduce security risks."
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "Ensure Legacy Authorization is set to Disabled on Kubernetes Engine Clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The 'enable_legacy_abac' feature is enabled, which uses legacy ABAC authorization and poses a security risk by not adhering to modern RBAC standards."
    },
    {
      "check_id": "CKV_GCP_13",
      "title": "Ensure client certificate authentication to Kubernetes Engine Clusters is disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Client certificate authentication is enabled, which can increase the attack surface if not properly managed."
    },
    {
      "check_id": "CKV_GCP_12",
      "title": "Ensure Network Policy is enabled on Kubernetes Engine Clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "CRITICAL",
      "explanation": "Network policies are not enabled, which can lead to unrestricted communication between pods and increase the risk of lateral movement in case of a compromise."
    },
    {
      "check_id": "CKV_GCP_20",
      "title": "Ensure master authorized networks is set to enabled in GKE clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Master authorized networks are not configured, which can expose the Kubernetes API server to unauthorized access."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = false\n  enable_legacy_abac = false\n  master_auth {\n    username = \"${var.master_username}\"\n    password = \"${var.master_password}\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n  network_policy {\n    enabled = true\n  }\n  master_authorized_networks_config {\n    cidr_blocks = [\n      {\n        cidr_block   = \"192.168.0.0/16\"\n        display_name = \"internal-network\"\n      }\n    ]\n  }\n}",
  "fix_summary": "Disabled 'enable_kubernetes_alpha' and 'enable_legacy_abac' to remove alpha features and legacy authorization. Disabled client certificate issuance for master authentication. Enabled network policies to restrict pod communication and added master authorized networks to limit API server access."
}
